using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Windows.Forms;
namespace Overclock {
 static class Theme {
  public static readonly Color Background=Color.FromArgb(12,12,14),Surface=Color.FromArgb(23,23,26),Raised=Color.FromArgb(33,32,36),Line=Color.FromArgb(49,46,50),Text=Color.FromArgb(242,239,240),Muted=Color.FromArgb(170,164,167),Accent=Color.FromArgb(224,113,120),AccentSoft=Color.FromArgb(191,105,114),Secondary=Color.FromArgb(174,169,173),Primary=Color.FromArgb(148,40,49),PrimaryHover=Color.FromArgb(170,48,58),SelectedSurface=Color.FromArgb(44,27,31),Warning=Color.FromArgb(243,173,119);
  static readonly Dictionary<string,Font> faces=new Dictionary<string,Font>();public static Font Face(float size,FontStyle style=FontStyle.Regular){string key=size+"/"+style;Font f;if(!faces.TryGetValue(key,out f)){f=new Font("Segoe UI",size,style);faces[key]=f;}return f;}
  public static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  public static Button Button(string text,bool primary=false){return new ModernButton{Text=text,Primary=primary,Width=145,Height=38,Margin=new Padding(0,0,10,0)};}
  public static Label Label(string text,int size=10,Color? color=null){return new Label{Text=text,ForeColor=color??Muted,Font=new Font("Segoe UI",size),AutoEllipsis=true};}
  public static void Combo(ComboBox c){c.BackColor=Raised;c.ForeColor=Text;c.FlatStyle=FlatStyle.Flat;c.DrawMode=DrawMode.OwnerDrawFixed;c.ItemHeight=26;c.Font=Theme.Face(10);if(c.Tag as string=="themed")return;c.Tag="themed";c.DrawItem+=(s,e)=>{if(e.Index<0)return;using(var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?Line:Raised))e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,c.Items[e.Index].ToString(),c.Font,new Rectangle(e.Bounds.X+8,e.Bounds.Y,e.Bounds.Width-12,e.Bounds.Height),Text,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};}
  public static DataGridView Grid(params string[] columns){var g=new DarkGrid{Dock=DockStyle.Fill,BackgroundColor=Surface,BorderStyle=BorderStyle.None,GridColor=Line,RowHeadersVisible=false,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,ReadOnly=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,EnableHeadersVisualStyles=false,CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal,ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None};g.DefaultCellStyle=new DataGridViewCellStyle{BackColor=Surface,ForeColor=Text,SelectionBackColor=Raised,SelectionForeColor=Text,Font=Theme.Face(10),Padding=new Padding(10,0,10,0)};g.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Raised,ForeColor=Muted,Font=Theme.Face(9,FontStyle.Bold),Padding=new Padding(10,0,10,0)};g.ColumnHeadersHeight=40;g.RowTemplate.Height=38;foreach(string c in columns)g.Columns.Add(c,c);return g;}
 }
 sealed class DarkGrid:DataGridView {public DarkGrid(){DoubleBuffered=true;}}
 sealed class ModernButton:Button {
  public bool Primary,Selected;bool hover;public ModernButton(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Theme.Background;ForeColor=Theme.Text;Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.AllPaintingInWmPaint,true);MouseEnter+=(s,e)=>{hover=true;Invalidate();};MouseLeave+=(s,e)=>{hover=false;Invalidate();};}
  protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Theme.Round(new RectangleF(0,0,Width-1,Height-1),8))using(var b=new SolidBrush(!Enabled?Theme.Surface:Primary?(hover?Theme.PrimaryHover:Theme.Primary):Selected?Theme.SelectedSurface:hover?Theme.Raised:Theme.Surface))e.Graphics.FillPath(b,path);if(Selected){using(var p=new Pen(Theme.Accent,3))e.Graphics.DrawLine(p,2,10,2,Height-10);}TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(12,0,Width-24,Height),!Enabled?Theme.Muted:Primary?Theme.Text:Selected?Theme.Accent:Theme.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);if(Focused)ControlPaint.DrawFocusRectangle(e.Graphics,new Rectangle(5,5,Width-10,Height-10));}
 }
 sealed class HardwareView:UserControl {
  readonly SensorClient client;readonly Dictionary<string,Collector> sources;readonly string category;readonly DataGridView grid=Theme.Grid("Reading","Value","Unit");readonly Timer timer=new Timer{Interval=1500};string last="";
  public HardwareView(string page,SensorClient sensors,Dictionary<string,Collector> providers){Dock=DockStyle.Fill;category=page;client=sensors;sources=providers;Controls.Add(grid);var caption=Theme.Label("LIVE READINGS   /   Values unavailable on this hardware are shown as —",9);caption.Dock=DockStyle.Top;caption.Height=34;Controls.Add(caption);timer.Tick+=(s,e)=>RefreshData();Disposed+=(s,e)=>timer.Dispose();timer.Start();RefreshData();}
  void RefreshData(){string key=category=="Memory"?"CPU":category;Collector c;if(sources.TryGetValue(key,out c))c.Request(false);if(category=="Memory"||category=="Inventory")sources["Inventory"].Request(false);if(category=="Storage")sources["Disk activity"].Request(false);string raw=c==null?"":c.Display;string filter=category=="CPU"?"cpu":category=="GPU"?"gpu":category=="Memory"?"ram":category=="Storage"?"storage":"";var sensors=client.Snapshot.Sensors.Where(v=>filter!=""&&v.Id.IndexOf(filter,StringComparison.OrdinalIgnoreCase)>=0).ToList();string signature=raw+string.Join("",sensors.Select(s=>s.Id+s.Value).ToArray())+(category=="Memory"?sources["Inventory"].Display:"");if(last==signature)return;last=signature;int top=grid.FirstDisplayedScrollingRowIndex;grid.Rows.Clear();if(category=="Storage"){foreach(string line in raw.Split('\n').Where(l=>l.StartsWith("Disk #"))){var p=line.Split('|');grid.Rows.Add(p[0].Trim()+" · "+p[1].Trim(),p.Length>3?p[3].Trim():"—",p.Length>4?p[4].Trim():"");if(p.Length>6)grid.Rows.Add("  Native serial",p[6].Replace("Native serial:","").Trim(),"");}}else foreach(string line in raw.Split('\n').Where(l=>!string.IsNullOrWhiteSpace(l))){if(category=="Memory"&&!line.StartsWith("RAM"))continue;var pieces=new System.Text.RegularExpressions.Regex(@"\s{2,}").Split(line.Trim(),2);grid.Rows.Add(pieces.Length>1?pieces[0]:"Device",pieces.Length>1?pieces[1]:line.Trim(),"");}foreach(var s in sensors)grid.Rows.Add((category=="Memory"?s.Hardware+" · ":"")+s.Name,s.Value.HasValue?s.Value.Value.ToString("0.##"):"—",Unit(s.Type));if(category=="Memory"){int module=0;foreach(System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(sources["Inventory"].Value,@"Manufacturer\s*:\s*([^\r\n]+)\s*PartNumber\s*:\s*([^\r\n]+)\s*Capacity\s*:\s*([^\r\n]+)\s*Speed\s*:\s*([^\r\n]+)")){module++;grid.Rows.Add("Module "+module,m.Groups[2].Value.Trim(),"");grid.Rows.Add("  Manufacturer",m.Groups[1].Value.Trim(),"");double bytes;if(double.TryParse(m.Groups[3].Value.Trim(),out bytes))grid.Rows.Add("  Capacity",(bytes/1073741824).ToString("0.#"),"GiB");grid.Rows.Add("  Frequency",m.Groups[4].Value.Trim(),"MHz");}}if(grid.Rows.Count==0)grid.Rows.Add("Provider status",raw==""?"Waiting for supported readings":raw,"");if(top>=0&&top<grid.Rows.Count)grid.FirstDisplayedScrollingRowIndex=top;grid.ClearSelection();}
  internal static string Unit(string type){switch(type){case "Temperature":return "°C";case "Clock":return "MHz";case "Load":return "%";case "Power":return "W";case "Voltage":return "V";case "Fan":return "RPM";case "Data":return "GiB";case "SmallData":return "MiB";case "Throughput":return "B/s";default:return type;}}
 }
}







